package com.example.payments.domain;

import java.math.BigDecimal;
import java.util.Objects;

public sealed interface PaymentMethod permits PaymentMethod.Card, PaymentMethod.BankTransfer {
    record Card(String last4) implements PaymentMethod {
        public Card {
            if (last4 == null || !last4.matches("\\d{4}")) {
                throw new IllegalArgumentException("last4 must be four digits");
            }
        }
    }

    record BankTransfer(String iban) implements PaymentMethod {
        public BankTransfer {
            if (iban == null || iban.isBlank()) {
                throw new IllegalArgumentException("iban is required");
            }
        }
    }
}

record Payment(BigDecimal amount, String currency, PaymentMethod method) {
    Payment {
        Objects.requireNonNull(amount, "amount");
        Objects.requireNonNull(currency, "currency");
        Objects.requireNonNull(method, "method");
        if (amount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        if (!currency.matches("[A-Z]{3}")) {
            throw new IllegalArgumentException("currency must be an ISO-4217 code");
        }
    }
}

sealed interface PaymentResult permits PaymentResult.Approved, PaymentResult.Declined {
    record Approved(String reference) implements PaymentResult {
        public Approved {
            if (reference == null || reference.isBlank()) {
                throw new IllegalArgumentException("reference is required");
            }
        }
    }

    record Declined(String reason) implements PaymentResult {
        public Declined {
            if (reason == null || reason.isBlank()) {
                throw new IllegalArgumentException("reason is required");
            }
        }
    }
}
```

`Payment`, `PaymentResult` and the variants are package-private in this example; make them public if they are part of the module API. The invariants fail fast and keep the model framework-free.
